import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    df['snapshot_date'] = pd.to_datetime(df['snapshot_date'])
except Exception:
    pass

try:
    sale_df = df[df['row_kind'] == 'sale'].copy()
except Exception:
    sale_df = df.copy()

try:
    latest_idx = sale_df.sort_values('snapshot_date').groupby('account_id')['snapshot_date'].idxmax()
    snap_df = sale_df.loc[latest_idx].copy()
except Exception:
    snap_df = sale_df.copy()

# EDA on all rows as loaded
try:
    eda = {}
    for col in ['balance', 'deposits']:
        s = df[col].dropna()
        eda[col] = {
            "mean": float(s.mean()), "std": float(s.std()),
            "min": float(s.min()), "max": float(s.max()),
            "median": float(s.median()), "count": int(s.count())
        }
    result['eda_summary'] = eda
except Exception:
    pass

# Correlations on one-row-per-account latest snapshot
try:
    corr_df = snap_df[['balance', 'deposits']].dropna()
    if len(corr_df) >= 30:
        r = corr_df['balance'].corr(corr_df['deposits'])
        if abs(r) >= 0.2:
            result['correlations']['balance__deposits'] = round(float(r), 4)
except Exception:
    pass

# Trends: weekly MoM on sale_df
try:
    sale_df['week'] = sale_df['snapshot_date'].dt.to_period('W')
    weekly = sale_df.groupby(['week', 'account_id']).apply(
        lambda g: g.sort_values('snapshot_date').iloc[-1]
    ).reset_index(drop=True)
    weekly_agg = weekly.groupby('week').agg(
        total_balance=('balance', 'sum'),
        total_deposits=('deposits', 'sum')
    ).reset_index().sort_values('week')
    if len(weekly_agg) >= 2:
        for col, label in [('total_balance', 'balance'), ('total_deposits', 'deposits')]:
            first_val = float(weekly_agg[col].iloc[0])
            last_val = float(weekly_agg[col].iloc[-1])
            if first_val != 0:
                pct = round((last_val - first_val) / abs(first_val) * 100, 2)
            else:
                pct = 0.0
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({
                "column": label, "period": "MoM",
                "direction": direction, "pct_change": pct, "segment": None
            })
except Exception:
    pass

# Segmentation
try:
    segs = []
    for seg_col in ['segment', 'branch']:
        for metric in ['balance', 'deposits']:
            grp = snap_df.groupby(seg_col)[metric].sum().nlargest(10)
            segs.append({
                "segment_column": seg_col, "metric_column": metric,
                "aggregation": "sum", "label": None,
                "results": [{"name": str(k), "value": round(float(v), 2)} for k, v in grp.items()]
            })
        cnt = snap_df.groupby(seg_col)['account_id'].count().nlargest(10)
        segs.append({
            "segment_column": seg_col, "metric_column": "account_id",
            "aggregation": "count", "label": None,
            "results": [{"name": str(k), "value": int(v)} for k, v in cnt.items()]
        })
    result['segments'] = segs
except Exception:
    pass

# Anomalies on all-rows balance and deposits
try:
    anomalies = []
    cap = 25
    for col in ['balance', 'deposits']:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min())
            s_t = (s + shift).apply(lambda x: np.log1p(x))
        else:
            s_t = s.copy()
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo_t, hi_t = q1 - 3 * iqr, q3 + 3 * iqr
        flagged = s_t[(s_t < lo_t) | (s_t > hi_t)]
        if len(flagged) / len(s_t) > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": "heavy-tailed distribution",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme values are natural, not flagged individually."
            })
            continue
        if abs(skew) > 2:
            lo_orig = np.expm1(lo_t) - shift
            hi_orig = np.expm1(hi_t) - shift
        else:
            lo_orig, hi_orig = lo_t, hi_t
        lo_4, hi_4 = q1 - 4 * iqr, q3 + 4 * iqr
        lo_5, hi_5 = q1 - 5 * iqr, q3 + 5 * iqr
        for idx in flagged.index:
            if len(anomalies) >= cap:
                break
            raw_val = float(df.loc[idx, col])
            t_val = float(s_t.loc[idx])
            if t_val > hi_5 or t_val < lo_5:
                sev = "critical"
            elif t_val > hi_4 or t_val < lo_4:
                sev = "high"
            else:
                sev = "medium"
            exp_range = f"[{round(lo_orig, 2)}, {round(hi_orig, 2)}]"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": raw_val,
                "expected_range": exp_range, "severity": sev,
                "explanation": f"{col} value {raw_val} lies outside expected range {exp_range}."
            })
    result['anomalies'] = anomalies
except Exception:
    pass

# Forecasting: simple linear extrapolation on weekly totals
try:
    if len(weekly_agg) >= 4:
        from scipy.stats import linregress
        x = np.arange(len(weekly_agg))
        y = weekly_agg['total_balance'].values
        slope, intercept, _, _, _ = linregress(x, y)
        fp = []
        for i in range(1, 5):
            pred_x = len(weekly_agg) - 1 + i
            pred_val = round(float(slope * pred_x + intercept), 2)
            fp.append({"period": f"week+{i}", "value": pred_val})
        result['forecast_points'] = fp
except Exception:
    pass

result['assumptions'] = [
    "EDA describes all rows as loaded; correlations and segmentation use one row per account_id (latest snapshot, sale rows only).",
    "Trends computed as weekly aggregates (sum of balance at latest per-account snapshot per week; sum of deposits).",
    "Anomaly detection uses 3×IQR extreme boundary; log1p applied for skewed columns.",
    "Forecast is a linear extrapolation of weekly total_balance; treat as indicative only.",
    "Rows with row_kind != 'sale' excluded from balance/deposit aggregations but included in EDA describe()."
]

# ─── Standard statistics (deterministic) ───
