_targets, _segs, _date, _hints = ['balance', 'deposits'], ['segment', 'branch'], 'snapshot_date', {'balance': ['last', ['account_id'], 'snapshot_date'], 'deposits': ['sum', [], None]}
# snapshot data: one row per entity for statistics over entities (domain_pack.entity_rows)
