                result['segments'] = [_x for _x in result['segments'] if not (isinstance(_x, dict) and _x.get('segment_column') == _s and _x.get('metric_column') == _c and str(_x.get('aggregation') or '').lower() in ('mean', 'avg', 'average'))]
