import numpy as np
import pandas as pd
from scipy import stats

# --- helpers ---
bad_status = ['reversed','pending','declined','failed','rejected',
              'charged off','charged_off','charged-off','charge off',
              'written off','written_off','write off','paid off','paid_off',
              'fully paid','closed']
bad_txn = ['REVERSAL','REV','REVERSAL CREDIT','REVERSAL DEBIT']

def sale_rows(d):
    mask = (
        d['row_kind'].isin(['sale']) &
        d['Currency'].str.upper().eq('USD') &
        ~d['Status'].str.lower().isin(bad_status) &
        ~d['Transaction Type'].str.upper().isin(bad_txn)
    )
    return d[mask].copy()

df_sale = sale_rows(df)

# --- EDA ---
try:
    for col in ['Amount', 'Balance After']:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

# --- CORRELATIONS (one row per Account ID, latest snapshot, sale rows) ---
try:
    snap = (df_sale.sort_values('Posting Date')
            .groupby('Account ID').last().reset_index())
    num_snap = snap[['Amount','Balance After']].dropna()
    if len(num_snap) >= 30:
        r, p = stats.pearsonr(num_snap['Amount'], num_snap['Balance After'])
        if abs(r) >= 0.2:
            result['correlations']['Amount__Balance After'] = round(float(r), 4)
except Exception:
    pass

# --- SEGMENTATION ---
try:
    seg_cols = ['Merchant Category', 'Transaction Type', 'Channel']
    metrics = ['Amount', 'Balance After']
    for seg in seg_cols:
        for met in metrics:
            top10 = df_sale[seg].value_counts().head(10).index
            sub = df_sale[df_sale[seg].isin(top10)]
            grp = sub.groupby(seg)[met].mean().reset_index()
            result['segments'].append({
                'segment_column': seg, 'metric_column': met,
                'aggregation': 'mean', 'label': None,
                'results': [{'name': str(r_['name']), 'value': round(float(r_['value']), 4)}
                            for r_ in grp.rename(columns={seg:'name', met:'value'}).to_dict('records')]
            })
    # count per segment
    for seg in seg_cols:
        top10 = df_sale[seg].value_counts().head(10)
        result['segments'].append({
            'segment_column': seg, 'metric_column': 'Transaction ID',
            'aggregation': 'count', 'label': 'transaction_count',
            'results': [{'name': str(k), 'value': float(v)} for k, v in top10.items()]
        })
    # net_flow ratio by Merchant Category
    mc_grp = df_sale.groupby('Merchant Category')['Amount'].sum()
    total_flow = mc_grp.sum()
    if total_flow != 0:
        mc_ratio = (mc_grp / total_flow).head(10)
        result['segments'].append({
            'segment_column': 'Merchant Category', 'metric_column': 'Amount',
            'aggregation': 'ratio', 'label': 'net_flow_share',
            'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in mc_ratio.items()]
        })
except Exception:
    pass

# --- ANOMALIES ---
try:
    anomaly_records = []
    for col in ['Amount', 'Balance After']:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = max(0, -s.min()) + 1 if s.min() < 0 else 0
        if abs(skew) > 2:
            vals = np.log1p(s + shift)
        else:
            vals = s.copy()
        q1, q3 = vals.quantile(0.25), vals.quantile(0.75)
        iqr = q3 - q1
        lo, hi = q1 - 3*iqr, q3 + 3*iqr
        extreme = (vals < lo) | (vals > hi)
        frac = extreme.sum() / len(vals)
        if frac > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'heavy-tailed; IQR bounds not meaningful',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        # convert bounds back to original space
        if abs(skew) > 2:
            lo_orig = np.expm1(lo) - shift
            hi_orig = np.expm1(hi) - shift
        else:
            lo_orig, hi_orig = lo, hi
        exp_range = f'[{lo_orig:.2f}, {hi_orig:.2f}]'
        extreme_idx = vals[extreme].index.tolist()
        for idx in extreme_idx[:25]:
            raw_val = float(s.loc[idx])
            v_log = float(vals.loc[idx])
            if v_log > q3 + 5*iqr:
                sev = 'critical'
            elif v_log > q3 + 4*iqr:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': raw_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {raw_val:.2f} lies outside expected range {exp_range}'
            })
        if len(anomaly_records) >= 25:
            break
    result['anomalies'] = anomaly_records[:25]
except Exception:
    pass

# --- TRENDS (beyond MoM computed externally) ---
try:
    df_sale['Posting Date'] = pd.to_datetime(df_sale['Posting Date'])
    df_sale_sorted = df_sale.sort_values('Posting Date')
    df_sale_sorted['week'] = df_sale_sorted['Posting Date'].dt.to_period('W')
    weekly = df_sale_sorted.groupby('week')['Amount'].sum().reset_index()
    weekly['Amount_roll7'] = weekly['Amount'].rolling(3, min_periods=1).mean()
    if len(weekly) >= 2:
        first_h = weekly['Amount_roll7'].iloc[:len(weekly)//2].mean()
        second_h = weekly['Amount_roll7'].iloc[len(weekly)//2:].mean()
        pct = float((second_h - first_h) / abs(first_h) * 100) if first_h != 0 else 0.0
        direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
        result['trends'].append({
            'column': 'Amount', 'period': '7d_rolling',
            'direction': direction, 'pct_change': round(pct, 4), 'segment': None
        })
    # Balance After: last snapshot per account per month
    df_sale['month'] = df_sale['Posting Date'].dt.to_period('M')
    bal_snap = (df_sale.sort_values('Posting Date')
                .groupby(['month','Account ID'])['Balance After'].last()
                .reset_index())
    monthly_bal = bal_snap.groupby('month')['Balance After'].sum().reset_index()
    if len(monthly_bal) >= 2:
        pct_bal = float((monthly_bal['Balance After'].iloc[-1] - monthly_bal['Balance After'].iloc[0])
                        / abs(monthly_bal['Balance After'].iloc[0]) * 100)
        direction_bal = 'up' if pct_bal > 1 else ('down' if pct_bal < -1 else 'flat')
        result['trends'].append({
            'column': 'Balance After', 'period': 'MoM',
            'direction': direction_bal, 'pct_change': round(pct_bal, 4), 'segment': None
        })
except Exception:
    pass

# --- FORECASTING (simple linear extrapolation on monthly net flow) ---
try:
    df_sale['Posting Date'] = pd.to_datetime(df_sale['Posting Date'])
    df_sale['month'] = df_sale['Posting Date'].dt.to_period('M')
    mflow = df_sale.groupby('month')['Amount'].sum().reset_index()
    mflow['t'] = np.arange(len(mflow))
    if len(mflow) >= 3:
        slope, intercept, _, _, _ = stats.linregress(mflow['t'], mflow['Amount'])
        for step in [1, 2, 3]:
            t_next = len(mflow) - 1 + step
            pred = float(intercept + slope * t_next)
            next_period = (mflow['month'].iloc[-1] + step).strftime('%Y-%m')
            result['forecast_points'].append({'period': next_period, 'value': round(pred, 2)})
except Exception:
    pass

# --- ASSUMPTIONS ---
result['assumptions'] = [
    "Sale rows: status not in bad_status, txn_type not in reversal list, currency=USD, row_kind='sale'.",
