        direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
        result['trends'].append({
            'column': 'Amount', 'period': '7d_rolling',
            'direction': direction, 'pct_change': round(pct, 4), 'segment': None
        })
    # Balance After: last snapshot per account per month
    df_sale['month'] = df_sale['Posting Date'].dt.to_period('M')
    bal_snap = (df_sale.sort_values('Posting Date')
                .groupby(['month','Account ID'])['Balance After'].last()
                .reset_index())
    monthly_bal = bal_snap.groupby('month')['Balance After'].sum().reset_index()
    if len(monthly_bal) >= 2:
        pct_bal = float((monthly_bal['Balance After'].iloc[-1] - monthly_bal['Balance After'].iloc[0])
                        / abs(monthly_bal['Balance After'].iloc[0]) * 100)
        direction_bal = 'up' if pct_bal > 1 else ('down' if pct_bal < -1 else 'flat')
        result['trends'].append({
            'column': 'Balance After', 'period': 'MoM',
            'direction': direction_bal, 'pct_change': round(pct_bal, 4), 'segment': None
        })
except Exception:
    pass

# --- FORECASTING (simple linear extrapolation on monthly net flow) ---
try:
    df_sale['Posting Date'] = pd.to_datetime(df_sale['Posting Date'])
    df_sale['month'] = df_sale['Posting Date'].dt.to_period('M')
    mflow = df_sale.groupby('month')['Amount'].sum().reset_index()
    mflow['t'] = np.arange(len(mflow))
    if len(mflow) >= 3:
        slope, intercept, _, _, _ = stats.linregress(mflow['t'], mflow['Amount'])
        for step in [1, 2, 3]:
            t_next = len(mflow) - 1 + step
            pred = float(intercept + slope * t_next)
            next_period = (mflow['month'].iloc[-1] + step).strftime('%Y-%m')
            result['forecast_points'].append({'period': next_period, 'value': round(pred, 2)})
except Exception:
    pass

# --- ASSUMPTIONS ---
result['assumptions'] = [
    "Sale rows: status not in bad_status, txn_type not in reversal list, currency=USD, row_kind='sale'.",
