def sale_rows(d):
    mask = (
        d['row_kind'].isin(['sale']) &
        d['Currency'].str.upper().eq('USD') &
        ~d['Status'].str.lower().isin(bad_status) &
        ~d['Transaction Type'].str.upper().isin(bad_txn)
    )
    return d[mask].copy()

