# --- ANOMALIES ---
try:
    anomaly_records = []
    for col in ['Amount', 'Balance After']:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = max(0, -s.min()) + 1 if s.min() < 0 else 0
        if abs(skew) > 2:
            vals = np.log1p(s + shift)
        else:
            vals = s.copy()
        q1, q3 = vals.quantile(0.25), vals.quantile(0.75)
        iqr = q3 - q1
        lo, hi = q1 - 3*iqr, q3 + 3*iqr
        extreme = (vals < lo) | (vals > hi)
        frac = extreme.sum() / len(vals)
        if frac > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'heavy-tailed; IQR bounds not meaningful',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        # convert bounds back to original space
        if abs(skew) > 2:
            lo_orig = np.expm1(lo) - shift
            hi_orig = np.expm1(hi) - shift
        else:
            lo_orig, hi_orig = lo, hi
        exp_range = f'[{lo_orig:.2f}, {hi_orig:.2f}]'
        extreme_idx = vals[extreme].index.tolist()
        for idx in extreme_idx[:25]:
            raw_val = float(s.loc[idx])
            v_log = float(vals.loc[idx])
            if v_log > q3 + 5*iqr:
                sev = 'critical'
            elif v_log > q3 + 4*iqr:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': raw_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {raw_val:.2f} lies outside expected range {exp_range}'
